// Fills a camera picture (bottom row first, 3 bytes a pixel, rows padded to 4 bytes) with the resting picture.
static void msFillPlaceholder(uint8_t *dib, int w, int h) {
    static uint8_t *src = nullptr;
    if (!src) {
        src = new uint8_t[kMsPhW * kMsPhH * 3];
        std::size_t o = 0;
        for (std::size_t r = 0; r < kMsPhRuns; r++) {
            const uint8_t *e = kMsPhData + r * 5;
            int n = e[0] | (e[1] << 8);
            for (int k = 0; k < n && o + 3 <= (std::size_t)kMsPhW * kMsPhH * 3; k++) { src[o++] = e[2]; src[o++] = e[3]; src[o++] = e[4]; }
        }
    }
    const int stride = (w * 3 + 3) & ~3;
    for (int y = 0; y < h; y++) {
        uint8_t *row = dib + (std::size_t)(h - 1 - y) * stride;
        const uint8_t *s = src + (std::size_t)(y * kMsPhH / h) * kMsPhW * 3;
        for (int x = 0; x < w; x++) { const uint8_t *p = s + (x * kMsPhW / w) * 3; row[x * 3] = p[0]; row[x * 3 + 1] = p[1]; row[x * 3 + 2] = p[2]; }
    }
}
